"""Regenerate crates/balatro-core/src/content/jokers/ids.rs from docs/mechanics/jokers.csv.

Variant order = CSV row order (`n`), which defines `JokerId::index()` (observation encoding).
Append new rows only; never reorder once training artifacts exist.

Usage: python3 scripts/gen_joker_ids.py
"""

import csv
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
CSV = ROOT / "docs/mechanics/jokers.csv"
OUT = ROOT / "crates/balatro-core/src/content/jokers/ids.rs"

HEADER = """//! `JokerId`: one variant per joker kind.
//!
//! GENERATED by `scripts/gen_joker_ids.py` from `docs/mechanics/jokers.csv` — do not edit by
//! hand. Variant order is the CSV row order and defines `index()` (used for observation
//! encoding), so append rows only, never reorder. The registry, `ALL` and `COUNT` follow
//! automatically.

use serde::{Deserialize, Serialize};

macro_rules! joker_ids {
    (@one $v:ident) => { 1 };
    ($($(#[$m:meta])* $v:ident),+ $(,)?) => {
        /// Joker kind.
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
        #[repr(u16)]
        pub enum JokerId {
            $($(#[$m])* $v),+
        }

        impl JokerId {
            /// All ids in declaration order.
            pub const ALL: [JokerId; 0 $(+ joker_ids!(@one $v))+] = [$(JokerId::$v),+];
            /// Number of ids.
            pub const COUNT: usize = Self::ALL.len();
            /// Stable 0-based index (position in `ALL`).
            pub const fn index(self) -> usize {
                self as usize
            }
        }
    };
}

joker_ids! {
"""


def main() -> None:
    rows = list(csv.DictReader(CSV.open()))
    ns = [int(r["n"]) for r in rows]
    assert ns == list(range(1, len(rows) + 1)), "CSV rows must be numbered 1..N in order"
    ids = [r["id"] for r in rows]
    assert len(set(ids)) == len(ids), "duplicate joker id"
    body = "".join(
        f"    /// {r['name']} (jokers.csv #{r['n']}, wave {r['wave']}).\n    {r['id']},\n"
        for r in rows
    )
    OUT.write_text(HEADER + body + "}\n")
    print(f"wrote {len(rows)} ids to {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
